1	package dashboard
2	
3	import (
4		"os"
5		"path/filepath"
6		"sort"
7		"strings"
8	
9		"gopkg.in/yaml.v3"
10	)
11	
12	// DaprComponent is a parsed Dapr component definition surfaced to the flow
13	// canvas. Category is derived from Type so the frontend can place the node
14	// without re-parsing: "pubsub" and "state" render inside the system boundary,
15	// "binding" renders outside it as an external sink.
16	type DaprComponent struct {
17		Name     string `json:"name"`     // metadata.name, e.g. "pubsub"
18		Type     string `json:"type"`     // spec.type, e.g. "pubsub.in-memory"
19		Category string `json:"category"` // "pubsub" | "state" | "binding" | "other"
20		File     string `json:"file"`     // source filename, for reference
21	}
22	
23	// componentYAML is the minimal shape read from a Dapr component file; every
24	// other field is ignored.
25	type componentYAML struct {
26		Metadata struct {
27			Name string `yaml:"name"`
28		} `yaml:"metadata"`
29		Spec struct {
30			Type string `yaml:"type"`
31		} `yaml:"spec"`
32	}
33	
34	// readComponents parses every *.yaml/*.yml file directly under dir into a
35	// DaprComponent. It is best-effort, mirroring listNames: a missing directory
36	// yields nil, and an unreadable or unparseable file is skipped rather than
37	// failing the whole response. Results are sorted by Name for determinism.
38	func readComponents(dir string) []DaprComponent {
39		ents, err := os.ReadDir(dir)
40		if err != nil {
41			return nil
42		}
43	
44		var comps []DaprComponent
45		for _, ent := range ents {
46			if ent.IsDir() || !isYAML(ent.Name()) {
47				continue
48			}
49			data, err := os.ReadFile(filepath.Join(dir, ent.Name()))
50			if err != nil {
51				continue
52			}
53			var doc componentYAML
54			if err := yaml.Unmarshal(data, &doc); err != nil {
55				continue
56			}
57			name := doc.Metadata.Name
58			if name == "" {
59				name = stem(ent.Name())
60			}
61			comps = append(comps, DaprComponent{
62				Name:     name,
63				Type:     doc.Spec.Type,
64				Category: classify(doc.Spec.Type),
65				File:     ent.Name(),
66			})
67		}
68	
69		sort.Slice(comps, func(i, j int) bool { return comps[i].Name < comps[j].Name })
70		return comps
71	}
72	
73	// classify maps a Dapr spec.type to the coarse category the flow canvas groups
74	// by: the segment before the first "." ("pubsub.in-memory" -> "pubsub"). An
75	// empty or dot-less type falls back to "other".
76	func classify(specType string) string {
77		prefix, _, ok := strings.Cut(specType, ".")
78		if !ok || prefix == "" {
79			return "other"
80		}
81		switch prefix {
82		case "pubsub", "state", "bindings":
83			if prefix == "bindings" {
84				return "binding"
85			}
86			return prefix
87		default:
88			return "other"
89		}
90	}
91	
92	func isYAML(name string) bool {
93		return strings.HasSuffix(name, ".yaml") || strings.HasSuffix(name, ".yml")
94	}
95	
96	// stem returns a filename without its extension.
97	func stem(name string) string {
98		return strings.TrimSuffix(name, filepath.Ext(name))
99	}
