1	package template
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"os"
8		"path/filepath"
9	)
10	
11	const (
12		// ScaffoldSchemaVersion is the newest scaffold.json schema this CLI
13		// understands. Bump only for incompatible changes; additive fields do
14		// not require a bump.
15		ScaffoldSchemaVersion = 1
16	
17		// ScaffoldRelPath is where the scaffold record lives inside a project.
18		ScaffoldRelPath = ".intropy/scaffold.json"
19	)
20	
21	var ErrScaffoldNotFound = errors.New("no " + ScaffoldRelPath + " found in current directory or any parent")
22	
23	// Scaffold is the committed record of what `int create` rendered. Unlike
24	// CreateResult it carries no outputDir — the file's location is the project
25	// root — and it is written into the project so later commands (e.g.
26	// `manifests create`) can re-fetch the exact template version.
27	type Scaffold struct {
28		SchemaVersion int            `json:"schemaVersion"`
29		Template      string         `json:"template"` // directory name in the template library repo
30		Owner         string         `json:"owner"`
31		Repo          string         `json:"repo"`
32		Version       string         `json:"version"`
33		Values        map[string]any `json:"values"`
34	}
35	
36	// WriteScaffold writes the scaffold record to <projectRoot>/.intropy/scaffold.json.
37	func WriteScaffold(projectRoot string, s Scaffold) error {
38		path := filepath.Join(projectRoot, filepath.FromSlash(ScaffoldRelPath))
39		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
40			return fmt.Errorf("write scaffold record: %w", err)
41		}
42		data, err := json.MarshalIndent(s, "", "  ")
43		if err != nil {
44			return fmt.Errorf("write scaffold record: %w", err)
45		}
46		data = append(data, '\n')
47		if err := os.WriteFile(path, data, 0o644); err != nil {
48			return fmt.Errorf("write scaffold record: %w", err)
49		}
50		return nil
51	}
52	
53	// LoadScaffold reads and parses a scaffold.json file.
54	func LoadScaffold(path string) (*Scaffold, error) {
55		data, err := os.ReadFile(path)
56		if err != nil {
57			return nil, fmt.Errorf("read scaffold record %s: %w", path, err)
58		}
59		var s Scaffold
60		if err := json.Unmarshal(data, &s); err != nil {
61			return nil, fmt.Errorf("parse scaffold record %s: %w", path, err)
62		}
63		return &s, nil
64	}
65	
66	// FindScaffold walks up from startDir looking for .intropy/scaffold.json.
67	// Returns the parsed record and the project root that contains it, or
68	// ErrScaffoldNotFound if the filesystem root is reached first.
69	func FindScaffold(startDir string) (*Scaffold, string, error) {
70		abs, err := filepath.Abs(startDir)
71		if err != nil {
72			return nil, "", fmt.Errorf("absolute path: %w", err)
73		}
74	
75		for {
76			candidate := filepath.Join(abs, filepath.FromSlash(ScaffoldRelPath))
77			if _, err := os.Stat(candidate); err == nil {
78				s, err := LoadScaffold(candidate)
79				if err != nil {
80					return nil, "", err
81				}
82				return s, abs, nil
83			} else if !os.IsNotExist(err) {
84				return nil, "", fmt.Errorf("stat %s: %w", candidate, err)
85			}
86	
87			parent := filepath.Dir(abs)
88			if parent == abs {
89				return nil, "", ErrScaffoldNotFound
90			}
91			abs = parent
92		}
93	}
