2	
3	import (
4		"context"
5		"fmt"
6		"io"
7		"net/http"
8		"path/filepath"
9		"sort"
10	)
11	
12	// DescribeOptions selects which template release to inspect. Fields mirror
13	// CreateOptions for the create flow so callers can share configuration.
14	type DescribeOptions struct {
15		Template  string // required; subdirectory in the templates repo holding template.yaml
16		Version   string
17		HTTP      *http.Client
18		UserAgent string
19	
20		// Test overrides; production callers leave these zero-valued.
21		Owner         string
22		Repo          string
23		GitHubBaseURL string
24	}
25	
26	func (o *DescribeOptions) applyDefaults() {
27		if o.Owner == "" {
28			o.Owner = defaultTemplateOwner
29		}
30		if o.Repo == "" {
31			o.Repo = defaultTemplateRepo
32		}
33		if o.UserAgent == "" {
34			o.UserAgent = "intropy-cli"
35		}
36	}
37	
38	// DescribeResult is the machine-readable view of a template manifest. The
39	// shape is stable and additive-only — Backstage's frontend renders the form
40	// from Parameters (a raw JSON Schema), so this contract is load-bearing.
41	type DescribeResult struct {
42		Template    string            `json:"template"`
43		Title       string            `json:"title,omitempty"`
44		Description string            `json:"description,omitempty"`
45		Tags        []string          `json:"tags,omitempty"`
46		Labels      map[string]string `json:"labels,omitempty"`
47		Owner       string            `json:"owner"`
48		Repo        string            `json:"repo"`
49		Version     string            `json:"version"`
50		Parameters  map[string]any    `json:"parameters"`
51	
52		// orderedFields preserves YAML declaration order for FormatText; YAML
53		// order is lost once Parameters round-trips through JSON, so we keep it
54		// here. Unexported so it stays out of the wire contract.
55		orderedFields []FieldSpec
56	}
57	
58	// Describe fetches the template tarball at the requested version (or latest)
59	// and returns its parsed template manifest. It performs the same fetch+extract
60	// path as Create but stops short of value resolution or rendering.
61	func Describe(ctx context.Context, opts DescribeOptions) (*DescribeResult, error) {
62		opts.applyDefaults()
63		if err := validateTemplateName(opts.Template); err != nil {
64			return nil, err
65		}
66	
67		gh := newConfiguredGitHub(opts.HTTP, opts.UserAgent, opts.GitHubBaseURL)
68		tag, err := resolveReleaseTag(ctx, gh, opts.Owner, opts.Repo, opts.Version)
69		if err != nil {
70			return nil, err
71		}
72	
73		templateRoot, cleanup, err := downloadTemplate(ctx, gh, opts.Owner, opts.Repo, tag, opts.Template, "intropy-describe-*")
74		if err != nil {
75			return nil, err
76		}
77		defer cleanup()
78	
79		tmpl, err := LoadTemplate(filepath.Join(templateRoot, templateManifestName))
80		if err != nil {
81			return nil, err
82		}
83	
84		return &DescribeResult{
85			Template:      tmpl.Metadata.Name,
86			Title:         tmpl.Metadata.Title,
87			Description:   tmpl.Metadata.Description,
88			Tags:          tmpl.Metadata.Tags,
89			Labels:        tmpl.Metadata.Labels,
90			Owner:         opts.Owner,
91			Repo:          opts.Repo,
92			Version:       tag,
93			Parameters:    tmpl.Spec.Parameters,
94			orderedFields: tmpl.Fields(),
95		}, nil
96	}
97	
98	// FormatText writes a human-readable summary of the template to w. The
99	// machine-readable form is JSON-marshaled DescribeResult — callers needing
100	// stable parsing should use that instead.
101	func (r *DescribeResult) FormatText(w io.Writer) {
102		title := r.Template
103		if r.Title != "" {
104			title = fmt.Sprintf("%s (%s)", r.Title, r.Template)
105		}
106		fmt.Fprintf(w, "%s @ %s/%s@%s\n", title, r.Owner, r.Repo, r.Version)
107		if r.Description != "" {
108			fmt.Fprintf(w, "\n%s\n", r.Description)
109		}
110		if len(r.Tags) > 0 {
111			fmt.Fprintf(w, "\nTags: %v\n", r.Tags)
112		}
113	
114		fields := r.orderedFields
115		if fields == nil {
116			// Result was JSON-unmarshaled by a downstream consumer; declaration
117			// order is gone. Fall back to alphabetical so output is at least
118			// deterministic.
119			fields = fieldsFromSchema(r.Parameters)
120		}
121		if len(fields) > 0 {
122			fmt.Fprintln(w, "\nParameters:")
123			for _, f := range fields {
124				marker := " "
125				if f.Required {
126					marker = "*"
127				}
128				label := f.Name
129				if f.Title != "" {
130					label = fmt.Sprintf("%s — %s", f.Name, f.Title)
131				}
132				fmt.Fprintf(w, "  %s %s [%s]\n", marker, label, f.Type)
133				if f.Description != "" {
134					fmt.Fprintf(w, "      %s\n", f.Description)
135				}
136				if f.Default != nil {
137					fmt.Fprintf(w, "      default: %v\n", f.Default)
138				}
139				if len(f.Enum) > 0 {
140					fmt.Fprintf(w, "      values: %v\n", f.Enum)
141				}
142				if f.Pattern != "" {
143					fmt.Fprintf(w, "      pattern: %s\n", f.Pattern)
144				}
145			}
146			fmt.Fprintln(w, "  (* = required)")
147		}
148	}
149	
150	// fieldsFromSchema returns FieldSpecs from a raw parameters block. Unlike
151	// Template.Fields it has no declaration-order information, so it falls back
152	// to alphabetical order for stable output.
153	func fieldsFromSchema(parameters map[string]any) []FieldSpec {
154		props, _ := parameters["properties"].(map[string]any)
155		if props == nil {
156			return nil
157		}
158		required := map[string]bool{}
159		if list, ok := parameters["required"].([]any); ok {
160			for _, r := range list {
161				if s, ok := r.(string); ok {
162					required[s] = true
163				}
164			}
165		}
166		names := make([]string, 0, len(props))
167		for k := range props {
168			names = append(names, k)
169		}
170		sort.Strings(names)
171		out := make([]FieldSpec, 0, len(names))
172		for _, name := range names {
173			raw, _ := props[name].(map[string]any)
174			out = append(out, fieldFromSchema(name, raw, required[name]))
175		}
176		return out
177	}
