1	package template
2	
3	import (
4		"fmt"
5		"os"
6	
7		"gopkg.in/yaml.v3"
8	)
9	
10	const (
11		APIVersionV1 = "intropy.dev/v1"
12		KindTemplate = "Template"
13	)
14	
15	// Template is the on-disk manifest for a template. The envelope mirrors the
16	// Kubernetes / Backstage shape so authors recognize it at a glance; the body
17	// is a deliberately narrow subset (no ui: extensions, no step pipeline).
18	type Template struct {
19		APIVersion string   `yaml:"apiVersion"`
20		Kind       string   `yaml:"kind"`
21		Metadata   Metadata `yaml:"metadata"`
22		Spec       Spec     `yaml:"spec"`
23	}
24	
25	type Metadata struct {
26		Name        string            `yaml:"name"`
27		Title       string            `yaml:"title,omitempty"`
28		Description string            `yaml:"description,omitempty"`
29		Tags        []string          `yaml:"tags,omitempty"`
30		Labels      map[string]string `yaml:"labels,omitempty"`
31	}
32	
33	type Spec struct {
34		Parameters map[string]any    `yaml:"parameters"`
35		Values     map[string]string `yaml:"values,omitempty"`
36	
37		// parameterOrder captures the declaration order of properties in
38		// spec.parameters.properties, since Go maps don't preserve YAML order.
39		// Populated by UnmarshalYAML.
40		parameterOrder []string
41	}
42	
43	// UnmarshalYAML decodes the spec and captures property declaration order
44	// so Fields() can return FieldSpecs in author-intended sequence.
45	func (s *Spec) UnmarshalYAML(node *yaml.Node) error {
46		type rawSpec struct {
47			Parameters map[string]any    `yaml:"parameters"`
48			Values     map[string]string `yaml:"values,omitempty"`
49		}
50		var r rawSpec
51		if err := node.Decode(&r); err != nil {
52			return err
53		}
54		s.Parameters = r.Parameters
55		s.Values = r.Values
56		s.parameterOrder = extractPropertyOrder(node)
57		return nil
58	}
59	
60	func extractPropertyOrder(specNode *yaml.Node) []string {
61		if specNode.Kind != yaml.MappingNode {
62			return nil
63		}
64		paramsNode := childByKey(specNode, "parameters")
65		if paramsNode == nil {
66			return nil
67		}
68		propsNode := childByKey(paramsNode, "properties")
69		if propsNode == nil || propsNode.Kind != yaml.MappingNode {
70			return nil
71		}
72		order := make([]string, 0, len(propsNode.Content)/2)
73		for i := 0; i < len(propsNode.Content); i += 2 {
74			order = append(order, propsNode.Content[i].Value)
75		}
76		return order
77	}
78	
79	func childByKey(mapping *yaml.Node, key string) *yaml.Node {
80		if mapping.Kind != yaml.MappingNode {
81			return nil
82		}
83		for i := 0; i < len(mapping.Content); i += 2 {
84			if mapping.Content[i].Value == key {
85				return mapping.Content[i+1]
86			}
87		}
88		return nil
89	}
90	
91	// FieldSpec is the prompter/CLI view of a single property in spec.parameters.
92	// Prompters and form code only consume FieldSpecs — they never touch the raw
93	// JSON Schema map.
94	type FieldSpec struct {
95		Name        string
96		Title       string
97		Description string
98		Type        string // "string" | "boolean" | "integer" | "number"
99		Enum        []any
100		Default     any
101		Pattern     string
102		Required    bool
103	}
104	
105	// Fields returns the JSON Schema properties as FieldSpecs in YAML declaration
106	// order.
107	func (t *Template) Fields() []FieldSpec {
108		props, _ := t.Spec.Parameters["properties"].(map[string]any)
109		if props == nil {
110			return nil
111		}
112		required := map[string]bool{}
113		if list, ok := t.Spec.Parameters["required"].([]any); ok {
114			for _, r := range list {
115				if s, ok := r.(string); ok {
116					required[s] = true
117				}
118			}
119		}
120		out := make([]FieldSpec, 0, len(t.Spec.parameterOrder))
121		for _, name := range t.Spec.parameterOrder {
122			raw, _ := props[name].(map[string]any)
123			out = append(out, fieldFromSchema(name, raw, required[name]))
124		}
125		return out
126	}
127	
128	func fieldFromSchema(name string, schema map[string]any, required bool) FieldSpec {
129		f := FieldSpec{Name: name, Required: required}
130		if schema == nil {
131			return f
132		}
133		f.Type, _ = schema["type"].(string)
134		f.Title, _ = schema["title"].(string)
135		f.Description, _ = schema["description"].(string)
136		f.Pattern, _ = schema["pattern"].(string)
137		f.Default = schema["default"]
138		if e, ok := schema["enum"].([]any); ok {
139			f.Enum = e
140		}
141		return f
142	}
143	
144	// LoadTemplate reads and validates a template.yaml file.
145	func LoadTemplate(path string) (*Template, error) {
146		data, err := os.ReadFile(path)
147		if err != nil {
148			return nil, fmt.Errorf("read template: %w", err)
149		}
150		var t Template
151		if err := yaml.Unmarshal(data, &t); err != nil {
152			return nil, fmt.Errorf("parse template: %w", err)
153		}
154		if err := t.validate(); err != nil {
155			return nil, fmt.Errorf("invalid template: %w", err)
156		}
157		return &t, nil
158	}
159	
160	func (t *Template) validate() error {
161		if t.APIVersion != APIVersionV1 {
162			return fmt.Errorf("unsupported apiVersion %q (want %q)", t.APIVersion, APIVersionV1)
163		}
164		if t.Kind != KindTemplate {
165			return fmt.Errorf("unsupported kind %q (want %q)", t.Kind, KindTemplate)
166		}
167		if t.Metadata.Name == "" {
168			return fmt.Errorf("metadata.name is required")
169		}
170		if t.Spec.Parameters == nil {
171			return fmt.Errorf("spec.parameters is required")
172		}
173		if typ, _ := t.Spec.Parameters["type"].(string); typ != "object" {
174			return fmt.Errorf(`spec.parameters.type must be "object"`)
175		}
176		return nil
177	}
