2	// (internal/dashboard). Integration matches template.ScaffoldEntry;
3	// IntegrationDetail adds the best-effort on-disk enrichment.
4	
5	export interface Integration {
6	  path: string
7	  schemaVersion: number
8	  template: string
9	  owner: string
10	  repo: string
11	  version: string
12	  values: Record<string, unknown>
13	  /** Directory carrying the .intropy record; the integration's display name. */
14	  name: string
15	  /** Parent directory of the integration; absent directly under the root. */
16	  system?: string
17	  /** Parent directory of the system; absent when the system sits at the root. */
