21	export interface FileDoc {
22	  name: string
23	  content: string
24	}
25	
26	/** A parsed Dapr component. `category` decides where the flow canvas draws it:
27	 *  `pubsub`/`state` inside the system boundary, `binding` outside as a sink. */
28	export interface DaprComponent {
29	  name: string
30	  type: string
31	  category: 'pubsub' | 'state' | 'binding' | 'other'
32	  file: string
33	}
