42	export interface Health {
43	  status: string
44	  version: string
45	}
46	
47	async function getJSON<T>(url: string): Promise<T> {
48	  const res = await fetch(url)
49	  if (!res.ok) {
50	    let message = `${res.status} ${res.statusText}`
51	    try {
52	      const body = (await res.json()) as { error?: string }
53	      if (body?.error) message = body.error
54	    } catch {
55	      // response had no JSON error body; keep the status line
56	    }
57	    throw new Error(message)
58	  }
59	  return (await res.json()) as T
60	}
61	
62	export const api = {
63	  listIntegrations: () => getJSON<Integration[]>('/api/integrations'),
64	  getIntegration: (path: string) =>
65	    getJSON<IntegrationDetail>(`/api/integrations/${path}`),
66	  /** Every integration enriched with pipeline steps + Dapr components for the flow canvas. */
67	  flow: () => getJSON<IntegrationDetail[]>('/api/flow'),
68	  health: () => getJSON<Health>('/api/health'),
69	}
