9	func TestReadComponentsMissingDir(t *testing.T) {
10		if got := readComponents(filepath.Join(t.TempDir(), "nope")); got != nil {
11			t.Errorf("readComponents(missing) = %v, want nil", got)
12		}
13	}
14	
15	func TestReadComponentsClassifies(t *testing.T) {
16		dir := t.TempDir()
17		write := func(name, body string) {
18			t.Helper()
19			if err := os.WriteFile(filepath.Join(dir, name), []byte(body), 0o644); err != nil {
20				t.Fatal(err)
21			}
22		}
23	
24		write("pubsub.yaml", "metadata:\n  name: pubsub\nspec:\n  type: pubsub.in-memory\n")
25		write("lookups.yaml", "metadata:\n  name: lookups\nspec:\n  type: state.in-memory\n")
26		write("local-storage.yaml", "metadata:\n  name: local-storage\nspec:\n  type: bindings.localstorage\n")
27		write("mystery.yaml", "metadata:\n  name: mystery\nspec:\n  type: secretstores.local.file\n")
28		// spec.type absent -> "other", name falls back to file stem.
29		write("bare.yml", "metadata:\n  name: bare\n")
30		// Non-YAML and malformed content are ignored, not surfaced.
31		write("readme.txt", "not a component")
32		write("broken.yaml", "metadata: [this is not: valid")
33	
34		got := readComponents(dir)
35	
36		want := map[string]struct{ typ, cat string }{
37			"pubsub":        {"pubsub.in-memory", "pubsub"},
38			"lookups":       {"state.in-memory", "state"},
39			"local-storage": {"bindings.localstorage", "binding"},
40			"mystery":       {"secretstores.local.file", "other"},
41			"bare":          {"", "other"},
42		}
43		if len(got) != len(want) {
44			t.Fatalf("got %d components, want %d: %+v", len(got), len(want), got)
45		}
46		// Sorted by Name.
47		for i := 1; i < len(got); i++ {
48			if got[i-1].Name > got[i].Name {
49				t.Errorf("components not sorted by name: %+v", got)
50			}
51		}
52		for _, c := range got {
53			w, ok := want[c.Name]
54			if !ok {
55				t.Errorf("unexpected component %q", c.Name)
56				continue
57			}
58			if c.Type != w.typ || c.Category != w.cat {
59				t.Errorf("%q = {type:%q cat:%q}, want {type:%q cat:%q}", c.Name, c.Type, c.Category, w.typ, w.cat)
60			}
61		}
62	}
