/* Integration card node */
.rf-int {
  width: 300px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 12px 14px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  cursor: pointer;
  transition:
    border-color 0.12s ease,
    box-shadow 0.12s ease;
}

.rf-int:hover {
  border-color: var(--text-muted);
}

.rf-int.selected {
  border-color: var(--accent);
  box-shadow: 0 0 0 1px var(--accent);
}

.rf-int-head {
  display: flex;
  align-items: center;
  gap: 8px;
}

.rf-int-icon {
  width: 18px;
  height: 18px;
  color: var(--accent);
  flex: 0 0 auto;
}

.rf-int-name {
  font-weight: 600;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf-int-tag {
  margin-left: auto;
  flex: 0 0 auto;
  font-size: 11px;
  color: var(--text-muted);
  background: var(--surface-2);
  border-radius: 999px;
  padding: 1px 8px;
}

.rf-int-row {
  display: flex;
  gap: 8px;
}

.rf-int-row-icon {
  width: 15px;
  height: 15px;
  margin-top: 3px;
  color: var(--text-muted);
  flex: 0 0 auto;
}

.rf-int-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}

.rf-int-empty {
  font-size: 12px;
  color: var(--text-muted);
}

.rf-chip {
  font-size: 11px;
  padding: 2px 8px;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: var(--surface);
}

.rf-chip.infra {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  color: var(--text-muted);
  background: var(--surface-2);
}

/* Shared infra node (pub/sub, database) — inside the boundary */
.rf-infra {
  width: 100%;
  height: 100%;
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 14px;
