const WORKSPACE_KEY = '__workspace__'

/** Which way data crosses the system boundary for an integration. */
type DataFlow = 'in' | 'out' | 'both' | 'internal'

// Fallback for scaffolds that pre-date the scaffold.json dataFlow field:
// direction by well-known template name. New templates should declare the
// intropy.dev/data-flow label instead of growing this map.
const TEMPLATE_DATA_FLOW: Record<string, DataFlow> = {
  'golden-record': 'in',
  transactional: 'both',
  'point-to-point': 'both',
  distribution: 'out',
  aggregator: 'internal',
}

function dataFlowOf(it: IntegrationDetail): DataFlow | undefined {
  return it.dataFlow ?? TEMPLATE_DATA_FLOW[it.template]
}

// Directional glyph per data flow; integrations with no known flow keep the
// generic chip icon rather than guessing a direction.
const DATA_FLOW_ICONS: Record<DataFlow, typeof MemoryIcon> = {
  in: InputIcon,
  out: OutputIcon,
  both: SyncAltIcon,
  internal: CycleIcon,
}

