// External bindings, outside the boundary. Declared inputs stack on the
// left as sources feeding the integration; everything else stacks on the
// right as a sink (an undeclared direction renders as a sink, unchanged
// from before direction existed — unknown is not guessed). A declared
// "input,output" sits on the right with arrowheads on both ends. Kept
// per-integration since each reads/writes its own endpoint.
let srcIndex = 0
let sinkIndex = 0
for (const it of items) {
  for (const c of it.components ?? []) {
    if (c.category !== 'binding') continue
    const extId = `ext:${it.path}:${c.name}`
    const isSource = c.direction === 'input'
    const isBidi = c.direction === 'input,output'
    nodes.push({
      id: extId,
      type: 'external',
      position: {
        x: isSource ? -(EXT_W + EXT_GAP) : groupWidth + EXT_GAP,
        y: contentTop + (isSource ? srcIndex : sinkIndex) * (EXT_H + EXT_VGAP),
      },
      style: { width: EXT_W, height: EXT_H },
      data: { name: c.name, type: c.type, direction: c.direction } satisfies ExtNodeData,
      draggable: true,
    })
    if (isSource) {
      edges.push({
        id: `e:${extId}:src:${it.path}`,
        source: extId,
        sourceHandle: 'out',
        target: it.path,
        targetHandle: 'in',
        markerEnd: { type: MarkerType.ArrowClosed },
        className: 'rf-edge-ext',
      })
      srcIndex++
    } else {
      edges.push({
        id: `e:${it.path}:ext:${extId}`,
        source: it.path,
        sourceHandle: 'ext',
        target: extId,
        targetHandle: 'in',
        markerEnd: { type: MarkerType.ArrowClosed },
        ...(isBidi && { markerStart: { type: MarkerType.ArrowClosed } }),
        className: 'rf-edge-ext',
      })
      sinkIndex++
    }
  }
}

